
WITH
targets AS MATERIALIZED(SELECT DISTINCT c.* FROM CR c JOIN rel_MODIFIES m ON m.src_id=c.node_id JOIN Spec s ON s.node_id=m.dst_id WHERE s.specNumber='38.214'),
events AS MATERIALIZED(SELECT DISTINCT src_id,dst_id FROM edge WHERE rel_type IN('PRESENTED_AT','MADE_AT')),
target_lines AS MATERIALIZED(SELECT t.node_id,t.title,j.key line0,j.value line FROM targets t,json_each(split_lines(coalesce(t.summaryOfChange,''))) j),
reverse_components AS MATERIALIZED(
 SELECT DISTINCT d.tdocNumber,l.node_id target_id,l.line FROM target_lines l,json_each(ids_json(l.line)) ident JOIN Tdoc d ON d.tdocNumber=ident.value
 WHERE EXISTS(SELECT 1 FROM events de JOIN events ce ON de.dst_id=ce.dst_id WHERE de.src_id=d.node_id AND ce.src_id=l.node_id)),
same_title AS MATERIALIZED(
 SELECT DISTINCT d.tdocNumber,t.node_id target_id FROM Tdoc d JOIN targets t ON title_key(d.title)=title_key(t.title)
 WHERE d.type IN('discussion','Discussion') AND regexp('(?i)^FLS\s*#?\s*\d+',coalesce(d.title,''))
 AND EXISTS(SELECT 1 FROM events de JOIN events ce ON de.dst_id=ce.dst_id WHERE de.src_id=d.node_id AND ce.src_id=t.node_id)),
combined_components AS MATERIALIZED(
 SELECT ident.value tdocNumber,l.node_id target_id,l.line FROM target_lines l,json_each(ids_json(l.line)) ident
 WHERE regexp('(?i)combined.*CR',coalesce(l.title,'')) AND regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',l.line) AND l.line LIKE ident.value||' %'),
all_records AS MATERIALIZED(SELECT a.*,coalesce(a.content,'')||char(10)||coalesce(a.contentWithEquations,'')||char(10)||coalesce(a.note,'') AS "full" FROM Agreement a WHERE EXISTS(SELECT 1 FROM rel_REFERENCES authored_reference
JOIN targets authored_target ON authored_target.node_id=authored_reference.dst_id
WHERE authored_reference.src_id=a.node_id)),
record_docs AS MATERIALIZED(
 SELECT DISTINCT a.node_id owner_id,d.*,json_object('tdocNumber',d.tdocNumber,'title',d.title,'type',d.type,'secretaryRemarks',d.secretaryRemarks,
       'typed214',EXISTS(SELECT 1 FROM targets t WHERE t.node_id=d.node_id) AND EXISTS(SELECT 1 FROM rel_REFERENCES direct_reference WHERE direct_reference.src_id=a.node_id AND direct_reference.dst_id=d.node_id),
       'targetNumber',CASE WHEN EXISTS(SELECT 1 FROM rel_REFERENCES direct_reference WHERE direct_reference.src_id=a.node_id AND direct_reference.dst_id=d.node_id) THEN coalesce((SELECT CAST(CAST(t.crNumber AS INTEGER)AS TEXT) FROM targets t WHERE t.node_id=d.node_id),'') ELSE '' END) doc_json FROM all_records a,json_each(ids_json(a.full)) ident JOIN Tdoc d ON d.tdocNumber=ident.value),
candidate AS MATERIALIZED(
 SELECT a.* FROM all_records a WHERE regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',a.full)
 OR EXISTS(SELECT 1 FROM record_docs d WHERE d.owner_id=a.node_id AND (
 EXISTS(SELECT 1 FROM targets t WHERE t.node_id=d.node_id)
 OR regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',coalesce(d.title,'')) OR regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',coalesce(d.secretaryRemarks,''))
 OR EXISTS(SELECT 1 FROM reverse_components rc WHERE rc.tdocNumber=d.tdocNumber)
 OR EXISTS(SELECT 1 FROM same_title st WHERE st.tdocNumber=d.tdocNumber)
 OR EXISTS(SELECT 1 FROM combined_components cc WHERE cc.tdocNumber=d.tdocNumber)))),
fields AS MATERIALIZED(
 SELECT a.*, 'content' fieldName,coalesce(a.content,'') fieldText,split_lines(a.content) lines FROM candidate a
 UNION ALL SELECT a.*,'contentWithEquations',coalesce(a.contentWithEquations,''),split_lines(a.contentWithEquations) FROM candidate a
 UNION ALL SELECT a.*,'note',coalesce(a.note,''),split_lines(a.note) FROM candidate a),
field_scope AS MATERIALIZED(
 SELECT f.*,coalesce((SELECT min(j.key)FROM json_each(f.lines)j WHERE regexp('^\s*R1-\d{7}(?!\d)\s*\t',j.value)),json_array_length(f.lines)) cut,
 line_at(f.lines,0) firstLine,
 coalesce((SELECT j.value FROM json_each(split_lines(f.content))j WHERE trim(j.value)<>'' ORDER BY j.key LIMIT 1),'')firstContent
 FROM fields f),
field_context AS MATERIALIZED(
 SELECT f.*,lines_text(f.lines,0,f.cut) ownText,
 (SELECT d.doc_json FROM record_docs d WHERE d.owner_id=f.node_id AND d.tdocNumber IN(SELECT value FROM json_each(ids_json(line_at(f.lines,f.cut)))) LIMIT 1)firstDocument,
 coalesce((SELECT j.value FROM json_each(f.lines)j WHERE trim(j.value)<>'' ORDER BY j.key LIMIT 1),'')firstNonempty
 FROM field_scope f),
line_context AS MATERIALIZED(
 SELECT f.*,j.key line0,j.value l, before_regex('(?i)\b(?:with\s+(?:a|the)\s+change\s+of|(?:cross[- ]?)?reference\s+to)\b',j.value) subject,
 line_at(f.lines,j.key-1)prev,line_at(f.lines,j.key+1)next,
 lines_text(f.lines,j.key+1,j.key+20)following20,lines_text(f.lines,j.key+1,j.key+5)following4,
 lines_text(f.lines,0,max(0,j.key-1))beforePrev,first_spec(j.value)firstTarget,j.key<=2 firstThreeLines,
 coalesce((SELECT ident.value FROM json_each(f.lines)h,json_each(ids_json(h.value))ident WHERE h.key<=j.key AND regexp('^\s*R1-\d{7}(?!\d)\s*\t',h.value) ORDER BY h.key DESC LIMIT 1),'')currentHeader,
 coalesce((SELECT json_group_array(json(d.doc_json)) FROM record_docs d WHERE d.owner_id=f.node_id AND d.tdocNumber IN(SELECT value FROM json_each(ids_json(j.value)))),'[]')lineDocs
 FROM field_context f,json_each(f.lines)j)
,contexts AS MATERIALIZED(SELECT e.*,
(normalize_text(coalesce(json_extract(captures('(?i)^\s*For\s+(?:a|an|the)\s+(.+?)\s+when\b',e.firstContent),'$[0]'),''))<>'' AND regexp('(?i)\b(?:shall|is expected to|are applied|is transmitted|is configured|the UE|a UE|UE determines|support|does not expect|can only)\b',coalesce(e.content,'')) AND (NOT regexp('(?i)\b(?:not|never)\s+(?:yet\s+)?(?:endorsed|approved|agreed|adopted)|\b(?:no consensus|no agreement|if agreed|if approved|previously agreed|earlier agreed|already agreed)\b|^\s*(?:Reason for change|Consequences if not approved):',e.firstLine)) AND EXISTS(SELECT 1 FROM record_docs d JOIN reverse_components rc ON rc.tdocNumber=d.tdocNumber WHERE d.owner_id=e.node_id AND regexp('(?i)\bcapture\s+the\s+agreements?\b',rc.line) AND instr(normalize_text(rc.line),normalize_text(coalesce(json_extract(captures('(?i)^\s*For\s+(?:a|an|the)\s+(.+?)\s+when\b',e.firstContent),'$[0]'),'')))>0)) AS ownNormativeExactCapturedScope,
(e.cut>0 AND e.cut<json_array_length(e.lines) AND (coalesce(json_extract(e.firstDocument,'$.typed214'),'')=1 OR (regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',coalesce(json_extract(e.firstDocument,'$.secretaryRemarks'),'')) AND regexp('(?i)\b(?:draft\s*)?CRs?\b',coalesce(json_extract(e.firstDocument,'$.secretaryRemarks'),'')) AND regexp('(?i)\b(?:(?:the\s*)?TPs?(?=\b|[0-9#_])|text proposals?\b|proposals?\s*\d)',coalesce(json_extract(e.firstDocument,'$.secretaryRemarks'),''))) OR (regexp('(?i)\b(?:draft\s*)?CRs?\b',coalesce(json_extract(e.firstDocument,'$.title'),'')) AND regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',e.ownText))) AND (NOT (regexp('(?i)^\s*(?:Endorse|The draft|The final|Send|Approve).*\bLS\b',e.ownText) AND (NOT regexp('(?i)\b(?:shall|is expected to|is not expected to|are applied|is transmitted|can only be|clarif(?:y|ied)|fix|add|remove|replace|amend|correct|apply existing agreements|further revised as follows|support\s+\w+\s*=)\b',e.ownText)))) AND (NOT (regexp('(?:37|38)\s*\.\s*\d{3}',e.firstLine) AND (NOT regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',e.firstLine)) AND (regexp('(?i)\b(?:is|are)\s+(?:endorsed|approved|agreed|adopted|agreeable)|\b(?:adopt|endorse|approve|accept|agree)\b',e.firstLine) OR regexp('(?i)\b(?:(?:the\s*)?TPs?(?=\b|[0-9#_])|text proposals?\b|proposals?\s*\d)',e.firstLine)))) AND NOT EXISTS(SELECT 1 FROM json_each(e.lines) x WHERE x.key<e.cut AND regexp('(?i)^\s*Follow\s*up\s+discussion\b',x.value)) AND (regexp('(?i)\b(?:shall|is expected to|is not expected to|are applied|is transmitted|can only be|clarif(?:y|ied)|fix|add|remove|replace|amend|correct|apply existing agreements|further revised as follows|support\s+\w+\s*=)\b',e.ownText) OR (regexp('(?i)\b(?:is|are)\s+(?:endorsed|approved|agreed|adopted|agreeable)|\b(?:adopt|endorse|approve|accept|agree)\b',e.ownText) AND regexp('(?i)\b(?:(?:the\s*)?TPs?(?=\b|[0-9#_])|text proposals?\b|proposals?\s*\d)',e.ownText) AND regexp('(?i)cover\s*sheet\s+of\s+the\s+CR',e.ownText))) AND ((NOT regexp('(?:37|38)\s*\.\s*\d{3}',e.ownText)) OR regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',e.ownText)) AND (NOT regexp('(?i)\b(?:not|never)\s+(?:yet\s+)?(?:endorsed|approved|agreed|adopted)|\b(?:no consensus|no agreement|if agreed|if approved|previously agreed|earlier agreed|already agreed)\b|^\s*(?:Reason for change|Consequences if not approved):',e.firstLine))) AS ownNormativeAdjacentTargetCR,
(e.firstLine<>'' AND regexp('(?i)\b(?:shall|is expected to|is not expected to|are applied|is transmitted|can only be|clarif(?:y|ied)|fix|add|remove|replace|amend|correct|apply existing agreements|further revised as follows|support\s+\w+\s*=)\b',e.firstLine) AND (NOT regexp('(?i)\b(?:not|never)\s+(?:yet\s+)?(?:endorsed|approved|agreed|adopted)|\b(?:no consensus|no agreement|if agreed|if approved|previously agreed|earlier agreed|already agreed)\b|^\s*(?:Reason for change|Consequences if not approved):',e.firstLine)) AND EXISTS(SELECT 1 FROM targets t WHERE EXISTS(SELECT 1 FROM events ae JOIN events ce ON ae.dst_id=ce.dst_id WHERE ae.src_id=e.node_id AND ce.src_id=t.node_id) AND trim(strip_prefix('(?i)^\s*(?:(?:Draft|Final)\s+)*(?:CRs?)\s+(?:on|for|to)\s*',coalesce(t.title,'')))<>'' AND instr(normalize_text(e.firstLine),normalize_text(trim(strip_prefix('(?i)^\s*(?:(?:Draft|Final)\s+)*(?:CRs?)\s+(?:on|for|to)\s*',coalesce(t.title,'')))))>0)) AS ownNormativeCompleteSameEventTitle,
(regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',coalesce(e.content,'')) AND regexp('(?i)\b(?:UE|gNB)\b.{0,40}\b(?:expected|shall|should|follows|is configured|is provided)\b',coalesce(e.content,'')) AND EXISTS(SELECT 1 FROM record_docs d JOIN combined_components cc ON cc.tdocNumber=d.tdocNumber WHERE d.owner_id=e.node_id AND EXISTS(SELECT 1 FROM events ae JOIN events ce ON ae.dst_id=ce.dst_id WHERE ae.src_id=e.node_id AND ce.src_id=cc.target_id))) AS ownNormativeNamedCombinedEntry,
(((((regexp('(?i)^(?:\|\s*)?[-_<=>\s]*(?:(?:Start|Begin|Text)\s*(?:of\s*)?(?:the\s*)?)?(?:TP(?:s)?(?=\b|[0-9#_])|Text\s+Proposal(?:s)?)(?:\b|(?=[0-9#_]))',trim(e.firstNonempty)) AND regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',before_regex('(?i)\b(?:with\s+(?:a|the)\s+change\s+of|cross[- ]?reference|reference\s+to|unchanged)\b',e.firstNonempty))) OR (regexp('(?i)^(?:\|\s*)?[-_<=>\s]*(?:TS\s*)?38\s*\.\s*\d{3}(?!\d)\b',trim(e.firstNonempty)) AND first_spec(e.firstNonempty)='214')) AND regexp('(?i)^(?:\|\s*)?[-_<=>\s]*(?:(?:Start|Begin|Text)\s*(?:of\s*)?(?:the\s*)?)?(?:TP(?:s)?(?=\b|[0-9#_])|Text\s+Proposal(?:s)?)(?:\b|(?=[0-9#_]))',e.firstNonempty)) OR (regexp('(?i)^\s*Reasons?\s+for\s+change',e.firstNonempty) AND EXISTS(SELECT 1 FROM json_each(e.lines) x WHERE regexp('(?i)(?:Start|Begin).{0,20}(?:text\s*proposal|TP)',x.value)) AND EXISTS(SELECT 1 FROM json_each(e.lines) x WHERE regexp('(?i)^\s*Summary\s+(?:of|for)\s+change',x.value)) AND (EXISTS(SELECT 1 FROM json_each(e.lines) x WHERE ((regexp('(?i)^(?:\|\s*)?[-_<=>\s]*(?:(?:Start|Begin|Text)\s*(?:of\s*)?(?:the\s*)?)?(?:TP(?:s)?(?=\b|[0-9#_])|Text\s+Proposal(?:s)?)(?:\b|(?=[0-9#_]))',trim(x.value)) AND regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',before_regex('(?i)\b(?:with\s+(?:a|the)\s+change\s+of|cross[- ]?reference|reference\s+to|unchanged)\b',x.value))) OR (regexp('(?i)^(?:\|\s*)?[-_<=>\s]*(?:TS\s*)?38\s*\.\s*\d{3}(?!\d)\b',trim(x.value)) AND first_spec(x.value)='214'))) OR first_spec(e.firstNonempty)='214'))) AND NOT EXISTS(SELECT 1 FROM json_each(e.lines) x WHERE regexp('(?i)\bno consensus\b.*\b(?:TP|text proposal)\b|\b(?:TP|text proposal).{0,40}\b(?:not agreed|not endorsed|not approved)\b',x.value))) AS firstOwnCompleteTargetTP,
(regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',coalesce(e.content,'')) AND regexp('(?i)above agreements imply to update specification',coalesce(e.note,''))) AS explicitCurrentSpecificationUpdate,
json_array_length(ids_json(e.l))=0 AS noLineIDs,
EXISTS(SELECT 1 FROM record_docs d JOIN targets t ON t.node_id=d.node_id WHERE d.owner_id=e.node_id AND d.tdocNumber=e.currentHeader) AS headerTyped214,
EXISTS(SELECT 1 FROM record_docs d JOIN targets t ON t.node_id=d.node_id WHERE d.owner_id=e.node_id AND t.crNumber IS NOT NULL AND regexp('(?i)\bCR\s*#?\s*0*'||CAST(CAST(t.crNumber AS INTEGER)AS TEXT)||'(?:\s*(?:rev|r)\s*\d+)?\b',e.l)) AS targetNumberTuple,
(regexp('^\s*R1-\d{7}(?!\d)\s*\t',e.l) AND EXISTS(SELECT 1 FROM record_docs d WHERE d.owner_id=e.node_id AND d.tdocNumber IN(SELECT value FROM json_each(ids_json(e.l))) AND EXISTS(SELECT 1 FROM targets t WHERE t.node_id=d.node_id)) AND EXISTS(SELECT 1 FROM json_each(e.lines) op WHERE op.key<e.line0 AND ((NOT regexp('(?i)\b(?:not|never)\s+(?:yet\s+)?(?:endorsed|approved|agreed|adopted)|\b(?:no consensus|no agreement|if agreed|if approved|previously agreed|earlier agreed|already agreed)\b|^\s*(?:Reason for change|Consequences if not approved):',op.value)) AND regexp('(?i)(?:following\s+(?:final\s+)?CRs?.{0,80}\b(?:agreed|endorsed|approved)|(?:final|draft)\s*CRs?.{0,60}\b(?:agreed|endorsed|approved).{0,20}\bin\s*:)|agreed\s+(?:TPs?|text proposals?).{0,150}(?:following|draft\s*CR)|(?:draft\s*CR).{0,80}endorsed\s+in\s*:',op.value)) AND NOT EXISTS(SELECT 1 FROM json_each(e.lines) bt WHERE bt.key>op.key AND bt.key<e.line0 AND ((NOT regexp('^\s*R1-\d{7}(?!\d)\s*\t',bt.value)) AND trim(bt.value)<>'' AND (NOT regexp('(?i)^\s*(?:\(?(?:Rel-|TS\s*38)|R1-\d|[,;]|MCC\b|(?:The )?spec(?:ification)? editor)',bt.value)))))) AS listedApproved214,
(regexp('^\s*R1-\d{7}(?!\d)\s*\t',e.l) AND EXISTS(SELECT 1 FROM record_docs d WHERE d.owner_id=e.node_id AND d.tdocNumber IN(SELECT value FROM json_each(ids_json(e.l))) AND EXISTS(SELECT 1 FROM targets t WHERE t.node_id=d.node_id)) AND EXISTS(SELECT 1 FROM json_each(e.lines) op WHERE op.key<e.line0 AND (regexp('(?i)^\s*(?:(?:Monday|Tuesday|Wednesday|Thursday|Friday)(?:\s+decision)?:\s*)?(?:The\s+)?(?:following\s+(?:(?:final|draft|alignment)\s+)?CRs?\s+(?:are\s+)?(?:agreed|endorsed|approved)|agreed\s+text\s+proposals?.*captured\s+in\s+the\s+following.*draft\s+CRs?)',op.value) AND (NOT regexp('(?i)not\s+(?:agreed|endorsed|approved)',op.value))) AND NOT EXISTS(SELECT 1 FROM json_each(e.lines) bt WHERE bt.key>op.key AND bt.key<e.line0 AND regexp('(?i)^\s*(?:Discussion:|Issue\s*#?\d|Decision:|No\s+(?:agreement|consensus)|Noted\b|For\s+further\s+study|Comeback\b)',bt.value)))) AS openedApprovedCRList214,
(EXISTS(SELECT 1 FROM record_docs d WHERE d.owner_id=e.node_id AND d.tdocNumber IN(SELECT value FROM json_each(ids_json(e.l))) AND EXISTS(SELECT 1 FROM targets t WHERE t.node_id=d.node_id)) AND (regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',e.l) OR (NOT regexp('(?i)\b(?:TS\s*)?\d{2}\.\d{3}\b',e.l))) AND EXISTS(SELECT 1 FROM json_each(e.lines) op WHERE op.key<e.line0 AND (regexp('(?i)following\s+(?:editorial\s+changes|text\s+proposals?|TPs?)',op.value) AND (regexp('(?i)\b(?:is|are)\s+(?:agreed|endorsed|approved|adopted|agreeable)|^\s*(?:Agree\s+on|Adopt|Endorse|Approve|Accept)\b',op.value) OR (regexp('(?i)\b(?:draft\s*)?CRs?\b',op.value) AND regexp('(?i)include\s+(?:them|these)',op.value))) AND (NOT regexp('(?i)\b(?:not|never)\s+(?:yet\s+)?(?:endorsed|approved|agreed|adopted)|\b(?:no consensus|no agreement|if agreed|if approved|previously agreed|earlier agreed|already agreed)\b|^\s*(?:Reason for change|Consequences if not approved):',op.value))) AND NOT EXISTS(SELECT 1 FROM json_each(e.lines) bt WHERE bt.key>op.key AND bt.key<e.line0 AND (regexp('^\s*R1-\d{7}(?!\d)\s*\t',bt.value) OR regexp('(?i)^\s*(?:Discussion:|Issue\s*#?\d|No\s+(?:consensus|agreement)|Noted\b|Comeback\b|Come\s+back\b|Reason\s+for\s+change|Consequences\s+if\s+not\s+approved)',bt.value))))) AS approvedTPList214,
(regexp('(?i)^\s*(?:(?:First|Second|Third|Fourth)\s+)?(?:TP(?:\s*#?\s*\d+(?:-\d+)*[A-Za-z]?)?|text\s+proposal|draft\s+proposal)\b',e.l) AND regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',e.l) AND (NOT regexp('(?i)\b(?:not|never)\s+(?:yet\s+)?(?:endorsed|approved|agreed|adopted)|\b(?:no consensus|no agreement|if agreed|if approved|previously agreed|earlier agreed|already agreed)\b|^\s*(?:Reason for change|Consequences if not approved):',e.l)) AND EXISTS(SELECT 1 FROM json_each(e.lines) op WHERE op.key<e.line0 AND (regexp('(?i)\b(?:is|are)\s+(?:endorsed|approved|agreed|adopted|agreeable)|\b(?:adopt|endorse|approve|accept|agree)\b',op.value) AND (NOT regexp('(?i)\b(?:not|never)\s+(?:yet\s+)?(?:endorsed|approved|agreed|adopted)|\b(?:no consensus|no agreement|if agreed|if approved|previously agreed|earlier agreed|already agreed)\b|^\s*(?:Reason for change|Consequences if not approved):',op.value)) AND regexp('(?i)\b(?:(?:the\s*)?TPs?(?=\b|[0-9#_])|text proposals?\b|proposals?\s*\d)',op.value) AND regexp('(?i)\b(?:following|all)\b',op.value) AND regexp('(?i)(?:alig(?:n)?ment.{0,30}\bCRs?\b|editor.{0,30}\bCRs?\b|\bCRs?\b.{0,30}alig(?:n)?ment)',(op.value||CASE WHEN op.key+1<e.line0 AND regexp('(?i)^\s*(?:To\s+be\s+included|For\s+inclusion)',line_at(e.lines,op.key+1)) THEN ' '||line_at(e.lines,op.key+1) ELSE '' END)) AND (NOT regexp('(?i)\b(?:comeback|come\s+back|to\s+be\s+(?:drafted|prepared)|will\s+prepare)\b',(op.value||CASE WHEN op.key+1<e.line0 AND regexp('(?i)^\s*(?:To\s+be\s+included|For\s+inclusion)',line_at(e.lines,op.key+1)) THEN ' '||line_at(e.lines,op.key+1) ELSE '' END))) AND ((NOT regexp('(?i)(?:TS\s*)?38\s*\.\s*\d{3}(?!\d)',(op.value||CASE WHEN op.key+1<e.line0 AND regexp('(?i)^\s*(?:To\s+be\s+included|For\s+inclusion)',line_at(e.lines,op.key+1)) THEN ' '||line_at(e.lines,op.key+1) ELSE '' END))) OR regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',(op.value||CASE WHEN op.key+1<e.line0 AND regexp('(?i)^\s*(?:To\s+be\s+included|For\s+inclusion)',line_at(e.lines,op.key+1)) THEN ' '||line_at(e.lines,op.key+1) ELSE '' END)))) AND NOT EXISTS(SELECT 1 FROM json_each(e.lines) bt WHERE bt.key>op.key AND bt.key<e.line0 AND (regexp('^\s*R1-\d{7}(?!\d)\s*\t',bt.value) OR regexp('(?i)^\s*(?:Discussion:|No\s+(?:agreement|consensus)|Come\s*back\b|For\s+(?:future|further)\b|From\s+(?:Monday|Tuesday|Wednesday|Thursday|Friday)\b)',bt.value))))) AS editorListComponent214,
EXISTS(SELECT 1 FROM record_docs d WHERE d.owner_id=e.node_id AND d.tdocNumber IN(SELECT value FROM json_each(ids_json(e.l))) AND (regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',coalesce(d.title,'')) AND regexp('(?i)\b(?:TP|text proposal|draft text)\b',coalesce(d.title,'')))) AS namedTargetTPTitle,
EXISTS(SELECT 1 FROM json_each(e.lines) h WHERE h.key>e.line0 AND regexp('^\s*R1-\d{7}(?!\d)\s*\t',h.value) AND EXISTS(SELECT 1 FROM record_docs d WHERE d.owner_id=e.node_id AND d.tdocNumber IN(SELECT value FROM json_each(ids_json(h.value))) AND regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',coalesce(d.title,'')) AND regexp('(?i)\b(?:TP|text proposal)\b',coalesce(d.title,''))) AND NOT EXISTS(SELECT 1 FROM json_each(e.lines) bt WHERE bt.key>e.line0 AND bt.key<h.key AND NOT regexp('^\s*R1-\d{7}(?!\d)\s*\t',bt.value) AND regexp('(?i)^\s*(?:Agreement|Decision|Endorse|Adopt)\b',bt.value))) AS followingTargetTPTitle,
EXISTS(SELECT 1 FROM json_each(e.lines) h WHERE h.key<e.line0 AND regexp('^\s*R1-\d{7}(?!\d)\s*\t',h.value) AND EXISTS(SELECT 1 FROM record_docs d WHERE d.owner_id=e.node_id AND d.tdocNumber IN(SELECT value FROM json_each(ids_json(h.value))) AND regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',coalesce(d.title,'')) AND regexp('(?i)\b(?:TP|text proposal)\b',coalesce(d.title,''))) AND NOT EXISTS(SELECT 1 FROM json_each(e.lines) bt WHERE bt.key>h.key AND bt.key<e.line0 AND NOT regexp('^\s*R1-\d{7}(?!\d)\s*\t',bt.value) AND regexp('(?i)^\s*(?:Agreement|Decision|Endorse|Adopt)\b',bt.value))) AS aboveTargetTPTitle,
