(regexp('(?i)\b(?:adopt(?:s|ed|ing)?|endorse(?:s|d)?|accept(?:s|ed)?|approve(?:s|d)?|agree(?:d|s)?)\b',e.l) AND regexp('(?i)\b(?:(?:the\s*)?TPs?(?=\b|[0-9#_])|text proposals?\b|proposals?\s*\d)',e.l) AND (NOT regexp('(?i)\b(?:not|never)\s+(?:yet\s+)?(?:endorsed|approved|agreed|adopted)|\b(?:no consensus|no agreement|if agreed|if approved|previously agreed|earlier agreed|already agreed)\b|^\s*(?:Reason for change|Consequences if not approved):',e.l)) AND (NOT ((regexp('(?i)^(?:\|\s*)?[-_<=>\s]*(?:(?:Start|Begin|Text)\s*(?:of\s*)?(?:the\s*)?)?(?:TP(?:s)?(?=\b|[0-9#_])|Text\s+Proposal(?:s)?)(?:\b|(?=[0-9#_]))',trim(e.l)) AND regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',before_regex('(?i)\b(?:with\s+(?:a|the)\s+change\s+of|cross[- ]?reference|reference\s+to|unchanged)\b',e.l))) OR (regexp('(?i)^(?:\|\s*)?[-_<=>\s]*(?:TS\s*)?38\s*\.\s*\d{3}(?!\d)\b',trim(e.l)) AND first_spec(e.l)='214'))) AND (NOT regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',e.subject)) AND (NOT regexp('(?i)^\s*(?:Reason(?:s)?\s+for\s+change|Summary\s+(?:of|for)\s+change|Consequences?\s+if\s+not\s+approved)',e.l)) AND ((regexp('(?i)\babove\b',e.l) AND EXISTS(SELECT 1 FROM json_each(e.lines) dd WHERE dd.key<e.line0 AND ((regexp('(?i)^(?:\|\s*)?[-_<=>\s]*(?:(?:Start|Begin|Text)\s*(?:of\s*)?(?:the\s*)?)?(?:TP(?:s)?(?=\b|[0-9#_])|Text\s+Proposal(?:s)?)(?:\b|(?=[0-9#_]))',trim(dd.value)) AND regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',before_regex('(?i)\b(?:with\s+(?:a|the)\s+change\s+of|cross[- ]?reference|reference\s+to|unchanged)\b',dd.value))) OR (regexp('(?i)^(?:\|\s*)?[-_<=>\s]*(?:TS\s*)?38\s*\.\s*\d{3}(?!\d)\b',trim(dd.value)) AND first_spec(dd.value)='214')) AND NOT EXISTS(SELECT 1 FROM json_each(e.lines) bt WHERE bt.key>=dd.key AND bt.key<e.line0 AND (regexp('(?i)^\s*(?:Decision:|Agreement(?:s)?\s*[:(]|\b(?:Adopt|Endorse|Approve|Accept|Agree)\b)',bt.value) AND regexp('(?i)\b(?:is|are)\s+(?:endorsed|approved|agreed|adopted|agreeable)|\b(?:adopt|endorse|approve|accept|agree)\b',bt.value) AND regexp('(?i)\b(?:(?:the\s*)?TPs?(?=\b|[0-9#_])|text proposals?\b|proposals?\s*\d)',bt.value))))) OR ((NOT regexp('(?i)\babove\b',e.l)) AND regexp('(?i)\b(?:following|below|corresponding|next|these)\b',e.l) AND EXISTS(SELECT 1 FROM json_each(e.lines) dd WHERE dd.key>e.line0 AND ((regexp('(?i)^(?:\|\s*)?[-_<=>\s]*(?:(?:Start|Begin|Text)\s*(?:of\s*)?(?:the\s*)?)?(?:TP(?:s)?(?=\b|[0-9#_])|Text\s+Proposal(?:s)?)(?:\b|(?=[0-9#_]))',trim(dd.value)) AND regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',before_regex('(?i)\b(?:with\s+(?:a|the)\s+change\s+of|cross[- ]?reference|reference\s+to|unchanged)\b',dd.value))) OR (regexp('(?i)^(?:\|\s*)?[-_<=>\s]*(?:TS\s*)?38\s*\.\s*\d{3}(?!\d)\b',trim(dd.value)) AND first_spec(dd.value)='214')) AND NOT EXISTS(SELECT 1 FROM json_each(e.lines) bt WHERE bt.key>e.line0 AND bt.key<=dd.key AND (regexp('(?i)^\s*(?:Decision:|Agreement(?:s)?\s*[:(]|\b(?:Adopt|Endorse|Approve|Accept|Agree)\b)',bt.value) AND regexp('(?i)\b(?:is|are)\s+(?:endorsed|approved|agreed|adopted|agreeable)|\b(?:adopt|endorse|approve|accept|agree)\b',bt.value) AND regexp('(?i)\b(?:(?:the\s*)?TPs?(?=\b|[0-9#_])|text proposals?\b|proposals?\s*\d)',bt.value))))))) AS selectedDeclaredTargetTP,
