,bridge_candidates AS(SELECT DISTINCT e.node_id,e.resolutionId FROM line_context e WHERE (regexp('(?i)^\s*Include\s+the\s+following\s+TP\b',e.l) AND regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',e.l) AND regexp('(?i)\balignment\s+CR\b',e.l) AND regexp('^\s*R1-\d{7}(?!\d)\s*\t',e.next) AND EXISTS(SELECT 1 FROM rel_REFERENCES br JOIN targets bt ON bt.node_id=br.dst_id WHERE br.src_id=e.node_id AND bt.tdocNumber IN(SELECT value FROM json_each(ids_json(e.next))))) OR ((regexp('(?i)\b(?:is|are)\s+(?:endorsed|approved|agreed|adopted|agreeable)|\b(?:adopt|endorse|approve|accept|agree)\b',e.l) AND regexp('(?i)\b(?:(?:the\s*)?TPs?(?=\b|[0-9#_])|text proposals?\b|proposals?\s*\d)',e.l) AND NOT regexp('(?i)\b(?:not|never)\s+(?:yet\s+)?(?:endorsed|approved|agreed|adopted)|\b(?:no consensus|no agreement|if agreed|if approved|previously agreed|earlier agreed|already agreed)\b|^\s*(?:Reason for change|Consequences if not approved):',e.l)) AND regexp('(?i)\b(?:below|following)\b',e.l) AND EXISTS(SELECT 1 FROM json_each(e.lines) j WHERE j.key>e.line0 AND regexp('(?i)\bStart\s+of\s+text\s+proposal\b',j.value) AND regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',j.value) AND regexp('(?i)\bwith\s+draft\s+CR\b',j.value) AND EXISTS(SELECT 1 FROM rel_REFERENCES br JOIN targets bt ON bt.node_id=br.dst_id WHERE br.src_id=e.node_id AND bt.tdocNumber IN(SELECT value FROM json_each(ids_json(j.value)))) AND NOT EXISTS(SELECT 1 FROM json_each(e.lines) k WHERE k.key>e.line0 AND k.key<=j.key AND regexp('^\s*R1-\d{7}(?!\d)\s*\t',k.value)))) OR ((regexp('(?i)\b(?:is|are)\s+(?:endorsed|approved|agreed|adopted|agreeable)|\b(?:adopt|endorse|approve|accept|agree)\b',e.l) AND regexp('(?i)\b(?:(?:the\s*)?TPs?(?=\b|[0-9#_])|text proposals?\b|proposals?\s*\d)',e.l) AND NOT regexp('(?i)\b(?:not|never)\s+(?:yet\s+)?(?:endorsed|approved|agreed|adopted)|\b(?:no consensus|no agreement|if agreed|if approved|previously agreed|earlier agreed|already agreed)\b|^\s*(?:Reason for change|Consequences if not approved):',e.l)) AND regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',e.l) AND EXISTS(SELECT 1 FROM json_each(e.lines) j WHERE j.key>e.line0 AND j.key<json_array_length(e.lines)-1 AND regexp('(?i)^\s*Final\s+CR\s+in\s*:\s*$',j.value) AND regexp('^\s*R1-\d{7}(?!\d)\s*\t',line_at(e.lines,j.key+1)) AND EXISTS(SELECT 1 FROM rel_REFERENCES br JOIN targets bt ON bt.node_id=br.dst_id WHERE br.src_id=e.node_id AND bt.tdocNumber IN(SELECT value FROM json_each(ids_json(line_at(e.lines,j.key+1))))))) OR (regexp('(?i)\b(?:include\s+it|include\s+this)\b',e.l) AND regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',e.l) AND regexp('(?i)\balignment\s+CR\b',e.l) AND EXISTS(SELECT 1 FROM json_each(e.lines) j JOIN rel_REFERENCES br ON br.src_id=e.node_id JOIN targets bt ON bt.node_id=br.dst_id WHERE j.key<e.line0 AND regexp('^\s*R1-\d{7}(?!\d)\s*\t',j.value) AND bt.tdocNumber IN(SELECT value FROM json_each(ids_json(j.value))) AND regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',coalesce(bt.title,'')) AND NOT EXISTS(SELECT 1 FROM json_each(e.lines) k WHERE k.key>=j.key AND k.key<e.line0 AND regexp('^\s*={3,}',k.value)))) OR ((e.cut>0 AND e.cut<json_array_length(e.lines) AND EXISTS(SELECT 1 FROM rel_REFERENCES br JOIN targets bt ON bt.node_id=br.dst_id WHERE br.src_id=e.node_id AND bt.tdocNumber IN(SELECT value FROM json_each(ids_json(line_at(e.lines,e.cut))))) AND NOT EXISTS(SELECT 1 FROM json_each(e.lines) k WHERE k.key<e.cut AND (regexp('(?i)^\s*(?:Issue\s*#?\s*\d|Reference signals\b|[-* ]*End\s+of\s+(?:TP|text\s+proposal|change\s+request))',k.value) OR regexp('(?i)^\s*Follow\s*up\s+discussion\b',k.value))) AND NOT regexp('(?i)\b(?:down[- ]select(?:ion)?(?:\s+one)?|one of (?:the )?following(?:s)?)\b',e.ownText) AND NOT (regexp('(?i)\bOpt(?:ion)?\s*1\s*:',e.ownText) AND regexp('(?i)\bOpt(?:ion)?\s*2\s*:',e.ownText)) AND NOT (regexp('(?i)(?:TS\s*)?38\s*\.\s*\d{3}(?!\d)',e.firstLine) AND NOT regexp('(?i)(?:TS\s*)?38\s*\.\s*214(?!\d)',e.firstLine)) AND NOT regexp('(?i)\b(?:not|never)\s+(?:yet\s+)?(?:endorsed|approved|agreed|a